import { getNotificationPreference } from "./db";
import { toggleNotificationPreference } from "./actions";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <section>
        <h2>Notifications</h2>
        <p>
          Notifications are currently{" "}
          <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>.
        </p>
        <form action={toggleNotificationPreference}>
          <button type="submit">
            Turn {notificationsEnabled ? "OFF" : "ON"}
          </button>
        </form>
      </section>
    </main>
  );
}

